import type { MediaAsset } from "./types";
import generated from "./media.generated.json";

/** The media registry: every image on the site, with its licence and credit.
 * Generated by scripts/media/process.py; edit alt text there, not here. */
export const MEDIA = generated as MediaAsset[];
const BY_ID = new Map(MEDIA.map((m) => [m.id, m]));

export function media(id: string): MediaAsset {
  const m = BY_ID.get(id);
  if (!m) throw new Error(`Unknown media id: ${id}`);
  return m;
}

export function hasMedia(id: string) {
  return BY_ID.has(id);
}

const BASE = process.env.NEXT_PUBLIC_BASE_PATH ?? "";
export const asset = (path: string) => `${BASE}${path}`;
export const small = (m: MediaAsset) => asset(m.src.replace(/\.webp$/, "-sm.webp"));
